import { Button, styled, Tab, Tabs } from "@mui/material";
import "./App.css";
import { InsertJsonModal } from "./modals/InsertJsonModal";
import { useState } from "react";
import { useLocalStorage } from "./hooks/useLocalStorage";
import { SavedJson } from "./typings";
import { ContentPage } from "./content/content";
import "react-json-view-lite/dist/index.css";

const Main = styled("main")`
  height: 100vh;
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 5fr;
`;

const Sidebar = styled("aside")`
  width: 100%;
  height: 100%;
  background-color: black;
`;

const Content = styled("div")`
  width: 100%;
  height: 100%;
  background-color: black;
`;

const SavedJsonTab = styled(Tab)`
  color: white;
  &:hover {
    background-color: #021073;
  }
  &.Mui-selected {
    background-color: #021073;
    color: white;
  }
`;

function App() {
  const [savedJson, _, reload] = useLocalStorage<SavedJson[]>("savedJson", []);
  const [jsonModalOpen, setJsonModalOpen] = useState(false);
  const [savedJsonTabIndex, setSavedJsonTabIndex] = useState<number | null>(
    null
  );
  return (
    <>
      <Main>
        <Sidebar>
          <h1 style={{ color: "white" }}>Entity Viewer</h1>
          <Button
            variant="contained"
            color="primary"
            onClick={() => setJsonModalOpen(true)}
            style={{ marginBottom: "20px" }}
          >
            Insert JSON
          </Button>
          <Tabs
            value={savedJsonTabIndex}
            variant="scrollable"
            scrollButtons={false}
            aria-label="scrollable prevent tabs example"
          >
            {savedJson.map((json, index) => (
              <SavedJsonTab
                key={json.id}
                label={json.name || json.id}
                onClick={() => setSavedJsonTabIndex(index)}
              />
            ))}
          </Tabs>
        </Sidebar>
        <Content>
          <ContentPage
            json={
              savedJsonTabIndex || savedJsonTabIndex === 0
                ? savedJson[savedJsonTabIndex]
                : null
            }
          />
        </Content>
      </Main>
      <InsertJsonModal
        open={jsonModalOpen}
        handleClose={() => {
          setJsonModalOpen(false);
          reload();
        }}
      />
    </>
  );
}

export default App;
